head.b:skin:
/* Blog Digest theme: base layout. The design layer (bd-redesign.js) styles everything on top of this. */
*,*::before,*::after{box-sizing:border-box}
html{-webkit-text-size-adjust:100%}
body{margin:0;background:#f7f4ee;color:#15171d;font:16px/1.6 system-ui,-apple-system,'Segoe UI',Roboto,Arial,sans-serif;overflow-x:hidden}
a{color:#e2462c;text-decoration:none}
img{max-width:100%;height:auto;border:0}
h1,h2,h3,h4{line-height:1.25;margin:0 0 .5em}
.container{max-width:1170px;margin:0 auto;padding:0 15px}
.clearfix{clear:both}
.skip-link{position:absolute;left:-9999px;top:0;z-index:10002;padding:10px 16px;background:#15171d;color:#fff}
.skip-link:focus{left:16px;top:16px}
.section,.widget{margin:0;padding:0}

/* Header */
#header-wrap{position:sticky;top:0;z-index:999;background:#fffdf9;border-bottom:1px solid #e8e2d6}
.header-header .container{display:flex;align-items:center;justify-content:space-between;gap:16px;min-height:72px}
.header-logo{padding:12px 0}
.header-image-wrapper{display:flex;align-items:center;gap:12px;color:#15171d}
.header-image-wrapper img{width:42px;height:42px;border-radius:12px}
.header-menu{display:flex;align-items:center}
#main-menu-nav{display:flex;align-items:center;gap:4px;list-style:none;margin:0;padding:0}
#main-menu-nav a{display:block;padding:0 12px;line-height:36px;border-radius:999px;color:#15171d;font-weight:600;font-size:14px}
.mobile-menu{display:none}
.slide-menu-toggle{display:none;cursor:pointer}
.slide-menu-toggle::before{content:'';display:block;width:18px;height:14px;
  background:linear-gradient(currentColor,currentColor) 0 0/100% 2px no-repeat,linear-gradient(currentColor,currentColor) 0 50%/100% 2px no-repeat,linear-gradient(currentColor,currentColor) 0 100%/100% 2px no-repeat}
.nav-active .slide-menu-toggle::before{background:linear-gradient(45deg,transparent 45%,currentColor 45%,currentColor 55%,transparent 55%),linear-gradient(-45deg,transparent 45%,currentColor 45%,currentColor 55%,transparent 55%)}
@media (max-width:980px){
  #main-menu{display:none}
  .slide-menu-toggle{display:grid;place-items:center}
  .mobile-menu{display:block;visibility:hidden;opacity:0;transform:translateY(-6px);transition:opacity .2s,transform .2s,visibility .2s}
  .nav-active .mobile-menu{visibility:visible;opacity:1;transform:none}
  .mobile-menu #main-menu-nav{display:block}
}

/* Content */
#content-wrapper{margin:30px auto 0}
#main-wrapper{width:100%}
.blog-posts{margin:0}
.grid-posts{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:22px}
.index-post{position:relative;background:#fff;border-radius:18px;overflow:hidden}
.index-post .post-image-wrap{position:relative;aspect-ratio:16/10;overflow:hidden;background:#fbf9f5}
.index-post .post-image-link,.index-post .post-thumb{display:block;width:100%;height:100%;object-fit:cover}
.index-post .post-tag{position:absolute;top:14px;left:14px}
.index-post .post-info{padding:18px 20px 22px}
.index-post .post-title{font-size:20px;margin:0 0 8px}
.index-post .post-title a{color:#15171d}
.post-meta,.post-meta a{font-size:13px;color:#5d6271}
.queryMessage{display:flex;justify-content:space-between;gap:12px;padding:10px 14px;margin:0 0 18px;font-size:14px}
.home-title{margin:0 0 18px;font-size:22px;font-weight:800}
.blog-pager{display:flex;justify-content:space-between;gap:12px;margin:30px 0 0}
.blog-pager a{display:inline-block;padding:10px 18px;border-radius:999px;background:#fff;border:1px solid #e8e2d6;color:#15171d;font-weight:700}
.item-post{max-width:800px;margin:0 auto}
.post-body{overflow-wrap:break-word}
.post-body img{border-radius:14px}
.post-body .separator{text-align:center}
.post-body .separator a{margin:0!important}
.post-body table{width:100%;border-collapse:collapse}
.post-body iframe{max-width:100%}
.post-footer{margin-top:34px}
.post-labels{display:flex;flex-wrap:wrap;align-items:center;gap:8px}
.label-head{display:flex;flex-wrap:wrap;gap:8px}
.share-links{display:flex;flex-wrap:wrap;gap:8px;list-style:none;margin:14px 0 0;padding:0}
.share-links a{display:grid;place-items:center;width:42px;height:42px;border-radius:50%;color:#fff}
.share-links svg{width:18px;height:18px;fill:currentColor}
.share-links .facebook a{background:#1877f2}.share-links .twitter a{background:#15171d}.share-links .linkedin a{background:#0a66c2}
.share-links .whatsapp a{background:#25d366}.share-links .email a{background:#6b7280}
.post-nav{list-style:none;margin:22px 0 0;padding:0}
.post-nav p{margin:0}
.errorWrap{text-align:center;padding:60px 0}
.errorWrap h3{font-size:96px;margin:0}
.blog-post-comments{max-width:800px;margin:24px auto 0}

/* Blogger comments */
#comments .comment-thread ol{list-style:none;margin:0;padding:0}
#comments .comment-thread li{margin:0 0 18px}
#comments .comment-block{padding:14px 16px;border-radius:14px;background:#fff;border:1px solid #e8e2d6}
#comments .avatar-image-container{float:left;margin-right:12px}
#comments .avatar-image-container img{border-radius:50%}
#comments .comment-header{font-size:14px}
#comments .comment-header .datetime{margin-left:8px;color:#5d6271}
#comments .comment-actions a{font-size:13px;margin-right:12px}
#comments .thread-toggle,#comments .continue a{font-size:14px;font-weight:600}
#comment-editor{width:100%}

/* Footer */
#footer-wrapper{margin-top:56px;padding:44px 0 30px;background:#12141b;color:#c5c9d3}
#footer-wrapper a{color:#c5c9d3}
.bd-foot-grid{display:grid;grid-template-columns:1.4fr 1fr 1fr;gap:36px}
.bd-foot-brand b{display:block;font-size:24px;color:#fff}
.bd-foot-brand p{margin:8px 0 0;max-width:36ch;font-size:15px;line-height:1.6}
.bd-foot-col h4{margin:0 0 12px;font-size:13px;letter-spacing:.12em;text-transform:uppercase;color:#fff}
.bd-foot-col ul{list-style:none;margin:0;padding:0;display:grid;gap:8px;font-size:15px}
#footer-gadgets{margin-top:30px}
#sub-footer-wrapper{background:#0a0b0f;color:#8d92a0;font-size:13.5px}
#sub-footer-wrapper .container{display:flex;justify-content:space-between;flex-wrap:wrap;gap:10px;padding-top:16px;padding-bottom:16px}
#sub-footer-wrapper a{color:#8d92a0}
@media (max-width:980px){.grid-posts{grid-template-columns:repeat(2,minmax(0,1fr))}.bd-foot-grid{grid-template-columns:1fr 1fr}.bd-foot-brand{grid-column:1/-1}}
@media (max-width:640px){.grid-posts{grid-template-columns:1fr}}

head.script:
//
window.dataLayer = window.dataLayer || [];
function gtag() { dataLayer.push(arguments); }
gtag('js', new Date());
gtag('config', 'G-2P00N18249');
//

//
/* Blog Digest design loader: asks GitHub which commit is current (at most once every 10 minutes per visitor), then
   loads seo/theme/bd-redesign.js from that commit. */
(function () {
  var repo = 'venkateshramu07-design/My_Repo', ver = '34baf3482e47249b385b14c35189cdc4e7ab0d0a', c = null, now = Date.now();
  try { c = JSON.parse(localStorage.getItem('bd-ver2') || 'null'); } catch (e) {}
  if (c && now - c.t < 6e5) ver = c.v;
  else {
    try {
      var x = new XMLHttpRequest();
      x.open('GET', 'https://raw.githubusercontent.com/' + repo + '/ccr-ee047f91-rbyv4x/seo/theme/version.txt', false);
      x.send();
      var t = (x.responseText || '').trim();
      if (x.status === 200 && /^[0-9a-f]{40}$/.test(t)) { ver = t; localStorage.setItem('bd-ver2', JSON.stringify({ v: t, t: now })); }
      else if (c) ver = c.v;
    } catch (e) { if (c) ver = c.v; }
  }
  document.write('<script src="https://cdn.jsdelivr.net/gh/' + repo + '@' + ver + '/seo/theme/bd-redesign.js"><\/script>');
})();
//

body.script:
//
(function () {
  var y = document.getElementById('bd-year'); if (y) y.textContent = new Date().getFullYear();
  var toggle = function () { document.body.classList.toggle('nav-active'); };
  document.addEventListener('click', function (e) {
    if (e.target.closest('.slide-menu-toggle')) toggle();
    else if (!e.target.closest('.mobile-menu')) document.body.classList.remove('nav-active');
  });
  document.addEventListener('keydown', function (e) {
    if ((e.key === 'Enter' || e.key === ' ') && e.target.classList && e.target.classList.contains('slide-menu-toggle')) { e.preventDefault(); toggle(); }
    if (e.key === 'Escape') document.body.classList.remove('nav-active');
  });
})();
//
